package com.crm.task.controller;
import com.crm.task.entity.Task; import com.crm.task.repository.TaskRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/tasks") public class TaskController { private final TaskRepository repo; public TaskController(TaskRepository repo){this.repo=repo;} @GetMapping public List<Task> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Task> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Task> create(@RequestBody Task x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} @PutMapping("/{id}") public ResponseEntity<Task> update(@PathVariable Long id,@RequestBody Task x){return repo.findById(id).map(e->{e.setTitle(x.getTitle());e.setDescription(x.getDescription());e.setStatus(x.getStatus());e.setPriority(x.getPriority());e.setAssignedTo(x.getAssignedTo());e.setDueDate(x.getDueDate());return ResponseEntity.ok(repo.save(e));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }